import pandas as pd

def clean(df):
    df = df.copy()
    # exact duplicate rows
    df = df.drop_duplicates()
    # island label variants
    island_map = {"Dram": "Dream", "Torgerson": "Torgersen"}
    if "island" in df.columns:
        df["island"] = df["island"].replace(island_map)
    # sex case variant
    if "sex" in df.columns:
        df["sex"] = df["sex"].astype(str).str.strip().str.lower()
    # numeric columns stored as text
    num_cols = ["flipper_length_mm", "body_mass_g", "year", "bill_length_mm", "bill_depth_mm"]
    for col in num_cols:
        if col in df.columns:
            s = df[col].astype(str).str.replace(",", "", regex=False)
            df[col] = pd.to_numeric(s, errors="coerce")
    return df

def answer(df):
    dfc = clean(df)
    means = dfc.groupby("species")["flipper_length_mm"].mean()
    # return plain dict with species -> average flipper length
    return {species: float(means[species]) for species in means.index}
